import{_ as l,a0 as o,w as d,s as r,ao as p,I as a,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 中复制文档 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中复制文档 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中复制文档 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中复制文档 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190809 Copying files in Linux","title":"在 Linux 中复制文档","tag":"201908","desc":""},"relativePath":"201908/20190809 Copying files in Linux.md","filePath":"[post].md"}'),c={name:"201908/20190809 Copying files in Linux.md"};function u(g,s,h,k,b,m){const n=o("Link");return d(),r("div",null,[s[40]||(s[40]=p('<h1 id="在-linux-中复制文档" tabindex="-1">在 Linux 中复制文档 <a class="header-anchor" href="#在-linux-中复制文档" aria-label="Permalink to “在 Linux 中复制文档”">​</a></h1><blockquote><p>了解在 Linux 中多种复制文档的方式以及各自的优点。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/23/053859f1stcjezllmj28e8.jpg" alt=""></p><p>在办公室里复印文档过去需要专门的员工与机器。如今，复制是电脑用户无需多加思考的任务。在电脑里复制数据是如此微不足道的事，以致于你还没有意识到复制就发生了，例如当拖动文档到外部硬盘的时候。</p><p>数字实体复制起来十分简单已是一个不争的事实，以致于大部分现代电脑用户从未考虑过其它的复制他们工作的方式。无论如何，在 Linux 中复制文档仍有几种不同的方式。每种方法取决于你的目的不同而都有其独到之处。</p><p>以下是一系列在 Linux、BSD 及 Mac 上复制文件的方式。</p><h3 id="在-gui-中复制" tabindex="-1">在 GUI 中复制 <a class="header-anchor" href="#在-gui-中复制" aria-label="Permalink to “在 GUI 中复制”">​</a></h3><p>如大多数操作系统一样，如果你想的话，你可以完全用 GUI 来管理文件。</p><h4 id="拖拽放下" tabindex="-1">拖拽放下 <a class="header-anchor" href="#拖拽放下" aria-label="Permalink to “拖拽放下”">​</a></h4><p>最浅显的复制文件的方式可能就是你以前在电脑中复制文件的方式：拖拽并放下。在大多数 Linux 桌面上，从一个本地文件夹拖拽放下到另一个本地文件夹是<em>移动</em>文件的默认方式，你可以通过在拖拽文件开始后按住 <code>Ctrl</code> 来改变这个行为。</p><p>你的鼠标指针可能会有一个指示，例如一个加号以显示你在复制模式。</p><p><img src="https://opensource.com/sites/default/files/uploads/copy-nautilus.jpg" alt="复制一个文件" title="Copying a file."></p><p>注意如果文件是放在远程系统上的，不管它是一个 Web 服务器还是在你自己网络里用文件共享协议访问的另一台电脑，默认动作经常是复制而不是移动文件。</p><h4 id="右击" tabindex="-1">右击 <a class="header-anchor" href="#右击" aria-label="Permalink to “右击”">​</a></h4><p>如果你觉得在你的桌面拖拽文档不够精准或者有点笨拙，或者这么做会让你的手离开键盘太久，你可以经常使用右键菜单来复制文件。这取决于你所用的文件管理器，但通常来说，右键弹出的关联菜单会包括常见的操作。</p>',15)),a("p",null,[s[1]||(s[1]=e("关联菜单的“复制”动作将你的",-1)),i(n,{href:"https://opensource.com/article/19/7/understanding-file-paths-and-how-use-them"},{default:t(()=>[...s[0]||(s[0]=[e("文件路径",-1)])]),_:1}),s[2]||(s[2]=e("（即文件在系统的位置）保存在你的剪切板中，这样你可以将你的文件",-1)),s[3]||(s[3]=a("em",null,"粘贴",-1)),s[4]||(s[4]=e("到别处：（LCTT 译注：此处及下面的描述不确切，这里并非复制的文件路径的“字符串”，而是复制了代表文件实体的对象/指针）",-1))]),s[41]||(s[41]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/uploads/copy-files-menu.jpg",alt:"从右键菜单复制文件",title:"Copying a file from the context menu."})],-1)),a("p",null,[s[6]||(s[6]=e("在这种情况下，你并没有将文件的内容复制到你的剪切版上。取而代之的是你复制了",-1)),i(n,{href:"https://opensource.com/article/19/7/understanding-file-paths-and-how-use-them"},{default:t(()=>[...s[5]||(s[5]=[e("文件路径",-1)])]),_:1}),s[7]||(s[7]=e("。当你粘贴时，你的文件管理器会查看剪贴板上的路径并执行复制命令，将相应路径上的文件粘贴到你准备复制到的路径。",-1))]),s[42]||(s[42]=p(`<h3 id="用命令行复制" tabindex="-1">用命令行复制 <a class="header-anchor" href="#用命令行复制" aria-label="Permalink to “用命令行复制”">​</a></h3><p>虽然 GUI 通常是相对熟悉的复制文件方式，用终端复制却更有效率。</p><h4 id="cp" tabindex="-1">cp <a class="header-anchor" href="#cp" aria-label="Permalink to “cp”">​</a></h4><p>在终端上等同于在桌面上复制和粘贴文件的最显而易见的方式就是 <code>cp</code> 命令。这个命令可以复制文件和目录，也相对直接。它使用熟悉的<em>来源</em>和<em>目的</em>（必须以这样的顺序）句法，因此复制一个名为 <code>example.txt</code> 的文件到你的 <code>Documents</code> 目录就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt ~/Documents</span></span></code></pre></div><p>就像当你拖拽文件放在文件夹里一样，这个动作并不会将 <code>Documents</code> 替换为 <code>example.txt</code>。取而代之的是，<code>cp</code> 察觉到 <code>Documents</code> 是一个文件夹，就将 <code>example.txt</code> 的副本放进去。</p><p>你同样可以便捷有效地重命名你复制的文档：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt ~/Documents/example_copy.txt</span></span></code></pre></div><p>重要的是，它使得你可以在与原文件相同的目录中生成一个副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt example.txt</span></span>
<span class="line"><span>cp: &#39;example.txt&#39; and &#39;example.txt&#39; are the same file.</span></span>
<span class="line"><span>$ cp example.txt example_copy.txt</span></span></code></pre></div><p>要复制一个目录，你必须使用 <code>-r</code> 选项（代表 <code>--recursive</code>，递归）。以这个选项对目录 <code>nodes</code> 运行 <code>cp</code> 命令，然后会作用到该目录下的所有文件。没有 <code>-r</code> 选项，<code>cp</code> 不会将目录当成一个可复制的对象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp notes/ notes-backup</span></span>
<span class="line"><span>cp: -r not specified; omitting directory &#39;notes/&#39;</span></span>
<span class="line"><span>$ cp -r notes/ notes-backup</span></span></code></pre></div><h4 id="cat" tabindex="-1">cat <a class="header-anchor" href="#cat" aria-label="Permalink to “cat”">​</a></h4>`,13)),a("p",null,[s[10]||(s[10]=a("code",null,"cat",-1)),s[11]||(s[11]=e(" 命令是最易被误解的命令，但这只是因为它表现了 ",-1)),i(n,{href:"https://linux.cn/article-11222-1.html"},{default:t(()=>[...s[8]||(s[8]=[e("POSIX",-1)])]),_:1}),s[12]||(s[12]=e(" 系统的极致灵活性。在 ",-1)),s[13]||(s[13]=a("code",null,"cat",-1)),s[14]||(s[14]=e(" 可以做到的所有事情中（包括其原意的连接文件的用途），它也能复制。例如说使用 ",-1)),s[15]||(s[15]=a("code",null,"cat",-1)),s[16]||(s[16]=e(" 你可以仅用一个命令就",-1)),i(n,{href:"https://opensource.com/article/19/2/getting-started-cat-command"},{default:t(()=>[...s[9]||(s[9]=[e("从一个文件创建两个副本",-1)])]),_:1}),s[17]||(s[17]=e("。你用 ",-1)),s[18]||(s[18]=a("code",null,"cp",-1)),s[19]||(s[19]=e(" 无法做到这一点。",-1))]),s[43]||(s[43]=p(`<p>使用 <code>cat</code> 复制文档要注意的是系统解释该行为的方式。当你使用 <code>cp</code> 复制文件时，该文件的属性跟着文件一起被复制，这意味着副本的权限和原件一样。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l -G -g</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span>
<span class="line"><span>$ cp foo.jpg bar.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 29 13:37  bar.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span></code></pre></div>`,2)),a("p",null,[s[21]||(s[21]=e("然而用 ",-1)),s[22]||(s[22]=a("code",null,"cat",-1)),s[23]||(s[23]=e(" 将一个文件的内容读取至另一个文件是让系统创建了一个新文件。这些新文件取决于你的默认 umask 设置。要了解 umask 更多的知识，请阅读 Alex Juarez 讲述 ",-1)),i(n,{href:"https://opensource.com/article/19/7/linux-permissions-101"},{default:t(()=>[...s[20]||(s[20]=[e("umask",-1)])]),_:1}),s[24]||(s[24]=e(" 以及权限概览的文章。",-1))]),s[44]||(s[44]=p(`<p>运行 <code>unmask</code> 获取当前设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask</span></span>
<span class="line"><span>0002</span></span></code></pre></div><p>这个设置代表在该处新创建的文档被给予 <code>664</code>（<code>rw-rw-r--</code>）权限，因为该 <code>unmask</code> 设置的前几位数字没有遮掩任何权限（而且执行位不是文件创建的默认位），并且写入权限被最终位所屏蔽。</p><p>当你使用 <code>cat</code> 复制时，实际上你并没有真正复制文件。你使用 <code>cat</code> 读取文件内容并将输出重定向到了一个新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat foo.jpg &amp;gt; baz.jpg</span></span>
<span class="line"><span>$ ls -l -G -g</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 29 13:37  bar.jpg</span></span>
<span class="line"><span>-rw-rw-r--. 1 57368 Jul 29 13:42  baz.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span></code></pre></div><p>如你所见，<code>cat</code> 应用系统默认的 umask 设置创建了一个全新的文件。</p><p>最后，当你只是想复制一个文件时，这些手段无关紧要。但如果你想复制文件并保持默认权限时，你可以用一个命令 <code>cat</code> 完成一切。</p><h4 id="rsync" tabindex="-1">rsync <a class="header-anchor" href="#rsync" aria-label="Permalink to “rsync”">​</a></h4><p>有着著名的同步源和目的文件的能力，<code>rsync</code> 命令是一个复制文件的多才多艺的工具。最为简单的，<code>rsync</code> 可以类似于 <code>cp</code> 命令一样使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync example.txt example_copy.txt</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>example.txt    example_copy.txt</span></span></code></pre></div><p>这个命令真正的威力藏在其能够<em>不做</em>不必要的复制的能力里。如果你使用 <code>rsync</code> 来将文件复制进目录里，且其已经存在在该目录里，那么 <code>rsync</code> 不会做复制操作。在本地这个差别不是很大，但如果你将海量数据复制到远程服务器，这个特性的意义就完全不一样了。</p><p>甚至在本地中，真正不一样的地方在于它可以分辨具有相同名字但拥有不同数据的文件。如果你曾发现你面对着同一个目录的两个相同副本时，<code>rsync</code> 可以将它们同步至一个包含每一个最新修改的目录。这种配置在尚未发现版本控制威力的业界十分常见，同时也作为需要从一个可信来源复制的备份方案。</p><p>你可以通过创建两个文件夹有意识地模拟这种情况，一个叫做 <code>example</code> 另一个叫做 <code>example_dupe</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir example example_dupe</span></span></code></pre></div><p>在第一个文件夹里创建文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;one&quot; &gt; example/foo.txt</span></span></code></pre></div><p>用 <code>rsync</code> 同步两个目录。这种做法最常见的选项是 <code>-a</code>（代表 “archive”，可以保证符号链接和其它特殊文件保留下来）和 <code>-v</code>（代表 “verbose”，向你提供当前命令的进度反馈）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -av example/ example_dupe/</span></span></code></pre></div><p>两个目录现在包含同样的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat example/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span></code></pre></div><p>如果你当作源分支的文件发生改变，目的文件也会随之跟新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;two&quot; &gt;&gt; example/foo.txt</span></span>
<span class="line"><span>$ rsync -av example/  example_dupe/</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>注意 <code>rsync</code> 命令是用来复制数据的，而不是充当版本管理系统的。例如假设有一个目的文件比源文件多了改变，那个文件仍将被覆盖，因为 <code>rsync</code> 比较文件的分歧并假设目的文件总是应该镜像为源文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;You will never see this note again&quot; &amp;gt; example_dupe/foo.txt</span></span>
<span class="line"><span>$ rsync -av example/  example_dupe/</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>如果没有改变，那么就不会有复制动作发生。</p><p><code>rsync</code> 命令有许多 <code>cp</code> 没有的选项，例如设置目标权限、排除文件、删除没有在两个目录中出现的过时文件，以及更多。可以使用 <code>rsync</code> 作为 <code>cp</code> 的强力替代或者有效补充。</p><h3 id="许多复制的方式" tabindex="-1">许多复制的方式 <a class="header-anchor" href="#许多复制的方式" aria-label="Permalink to “许多复制的方式”">​</a></h3><p>在 POSIX 系统中有许多能够达成同样目的的方式，因此开源的灵活性名副其实。我忘了哪个复制数据的有效方式吗？在评论区分享你的复制神技。</p><hr>`,29)),a("p",null,[s[26]||(s[26]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/19/8/copying-files-linux"},{default:t(()=>[...s[25]||(s[25]=[e("https://opensource.com/article/19/8/copying-files-linux",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[27]||(s[27]=[e("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[28]||(s[28]=[e("lujun9972",-1)])]),_:1}),s[33]||(s[33]=e(" 译者：",-1)),i(n,{href:"https://github.com/tomjlw"},{default:t(()=>[...s[29]||(s[29]=[e("tomjlw",-1)])]),_:1}),s[34]||(s[34]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[30]||(s[30]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[37]||(s[37]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[35]||(s[35]=[e("LCTT",-1)])]),_:1}),s[38]||(s[38]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[36]||(s[36]=[e("Linux中国",-1)])]),_:1}),s[39]||(s[39]=e(" 荣誉推出",-1))])])}const C=l(c,[["render",u]]);export{y as __pageData,C as default};
